window.QUEST_PYLIB = {"learner_env/constants.py": "\"\"\"constants.py - the same file the kit ships, trimmed to what the\npractice shop needs.\n\nIt exists so `from constants import BASE_URL` works here exactly as it\ndoes in learn/, and so assertions like\n\n    expect(page).to_have_url(BASE_URL + \"/view_cart\")\n\nare written the way a real suite writes them.\n\"\"\"\n\nBASE_URL = \"https://automationexercise.com\"\n\nPASSWORD = \"Practice123!\"\n\nACCOUNT = {\n    \"name\": \"Test Student\",\n    \"first_name\": \"Test\",\n    \"last_name\": \"Student\",\n    \"company\": \"QA Practice Inc\",\n    \"address\": \"123 Automation Street\",\n    \"address2\": \"Suite 42\",\n    \"country\": \"United States\",\n    \"state\": \"California\",\n    \"city\": \"San Francisco\",\n    \"zipcode\": \"94101\",\n    \"mobile_number\": \"5551234567\",\n}\n\nFAKE_CARD = {\n    \"name_on_card\": \"Test Student\",\n    \"number\": \"4242424242424242\",\n    \"cvc\": \"311\",\n    \"expiry_month\": \"12\",\n    \"expiry_year\": \"2030\",\n}\n", "learner_env/playwright/__init__.py": "\"\"\"The `playwright` package as the learner's code sees it.\n\nThis directory is only on sys.path inside Pyodide, never in CPython, so\nit can safely share a name with the real Playwright package. Its whole\njob is to make this line work in the browser:\n\n    from playwright.sync_api import Page, expect\n\n...which is the same line the kit's learn/ tests use, so a solution\nwritten here runs unchanged against a real browser.\n\"\"\"\n", "learner_env/playwright/sync_api.py": "\"\"\"Re-export of the shim under the name learners will use everywhere else.\"\"\"\n\nfrom playwright_lite.sync_api import (\n    Error,\n    Locator,\n    LocatorAssertions,\n    Page,\n    PageAssertions,\n    TimeoutError,\n    expect,\n)\n\n__all__ = [\n    \"Error\", \"Locator\", \"LocatorAssertions\", \"Page\", \"PageAssertions\",\n    \"TimeoutError\", \"expect\",\n]\n", "learner_env/utils/__init__.py": "\"\"\"utils - the kit's standalone helpers, available here under the same names.\"\"\"\n", "learner_env/utils/data.py": "\"\"\"utils/data.py - test data generators, mirroring the kit's own copy.\n\nNothing here touches the browser, which is exactly what makes it a\n\"util\" rather than a helper.\n\"\"\"\n\nimport time\n\n\ndef unique_email():\n    \"\"\"A brand-new email address every call.\n\n    Registration tests need this because the site remembers addresses:\n    reuse one and the second run fails with \"Email Address already\n    exist!\" - a real bug in a real suite, caused by a test that was not\n    independent.\n    \"\"\"\n    return f\"student.{int(time.time() * 1000)}@example.com\"\n", "playwright_lite/__init__.py": "\"\"\"playwright_lite - a browser-sized subset of the Playwright sync API.\n\nLearner code never imports this name. It imports\n`from playwright.sync_api import Page, expect`, exactly as the kit's own\ntests do; learner_env/playwright/ re-exports what is in here so a\nsolution written on the quest site is copy-pasteable into learn/.\n\"\"\"\n\nfrom playwright_lite import _runtime\nfrom playwright_lite.sync_api import Error, Locator, Page, TimeoutError, expect\n\n__all__ = [\"Error\", \"Locator\", \"Page\", \"TimeoutError\", \"_runtime\", \"expect\"]\n", "playwright_lite/_runtime.py": "\"\"\"Everything the shim needs that is not part of Playwright's own API.\n\nTwo jobs:\n\n1. Hold the bridge - the object that actually touches the DOM. In the\n   browser it is a JavaScript module registered by Pyodide; in the unit\n   tests it is a plain Python fake. The shim itself never knows which,\n   which is exactly why it can be tested without a browser.\n\n2. Record an action log. Challenges are graded on BEHAVIOUR - what the\n   learner's code did to the app - not on what their source looks like,\n   so we need an honest record of every call that reached the page.\n\"\"\"\n\nBRIDGE = None\n\n# One entry per action or assertion the learner's code performed.\nACTION_LOG = []\n\n\ndef bind(bridge):\n    \"\"\"Install the object that talks to the DOM (called once at boot).\"\"\"\n    global BRIDGE\n    BRIDGE = bridge\n\n\ndef reset_log():\n    \"\"\"Start a fresh recording. Called before every challenge run.\"\"\"\n    del ACTION_LOG[:]\n\n\ndef record(method, target, chain, args=None, ok=True, detail=\"\"):\n    \"\"\"Remember one thing the learner's code did.\"\"\"\n    ACTION_LOG.append({\n        \"method\": method,\n        \"target\": target,\n        # Which KINDS of locator were used (\"role\", \"css\", \"text\", ...).\n        # This is what lets a challenge insist on a role-based locator\n        # without ever string-matching the learner's source code.\n        \"kinds\": [step[\"k\"] for step in chain],\n        # The chain itself, so the site can re-resolve it afterwards and\n        # highlight what the learner's locator actually matched.\n        \"chain\": list(chain),\n        \"args\": list(args or []),\n        \"ok\": ok,\n        \"detail\": detail,\n        \"at\": BRIDGE.now() if BRIDGE is not None else 0,\n    })\n", "playwright_lite/sync_api.py": "\"\"\"playwright_lite - the real Playwright sync API, running in the browser.\n\nLearners import this as `from playwright.sync_api import Page, expect`\n(see learner_env/playwright/), so anything they write here can be pasted\nstraight into the kit's own tests and run against a real browser.\n\nThree things are deliberately faithful, because they are the things\nbeginners actually get wrong:\n\n  * AUTO-WAITING. Every action retries until the element is actionable\n    or the timeout runs out. The retry loop lives here, in Python, and\n    advances the app's virtual clock as it polls - so \"the element\n    appears after 600 ms\" is taught exactly, and identically on every\n    run.\n  * STRICT MODE. Two matches is an error, not a coin flip. That is why\n    the kit's Test Case 7 needs .first.\n  * ERROR MESSAGES. The wording below matches what real Playwright\n    prints, including the \"Call log:\" block, because reading those\n    messages is half the skill.\n\nWhat it is NOT: a browser. There are no frames, no network, no\ndownloads, no screenshots. Anything missing raises a clear\nNotImplementedError rather than quietly doing nothing.\n\"\"\"\n\nimport json\n\nfrom . import _runtime\n\n# Playwright's own defaults: 30 s for actions, 5 s for expect().\nDEFAULT_TIMEOUT = 30_000\n_expect_timeout = 5_000\n\n# How far the virtual clock jumps between retries. Fine-grained at first\n# so a 600 ms round trip resolves at exactly 600 ms, coarser afterwards\n# so a genuinely failing test reports quickly.\n_FINE_POLL = 100\n_COARSE_POLL = 500\n_FINE_WINDOW = 1_000\n\n\nclass Error(Exception):\n    \"\"\"Base class for every Playwright error (playwright.sync_api.Error).\"\"\"\n\n\nclass TimeoutError(Error):\n    \"\"\"Raised when an action or assertion runs out of time.\n\n    Yes, it shadows the builtin - so does the real\n    playwright.sync_api.TimeoutError, and matching it matters more here\n    than avoiding the shadow.\n    \"\"\"\n\n\n# --------------------------------------------------------------------------\n# Turning a locator chain back into the code that built it\n# --------------------------------------------------------------------------\n\ndef _q(value):\n    \"\"\"Quote a string the way Playwright prints it in a call log.\"\"\"\n    return '\"' + str(value).replace('\\\\', '\\\\\\\\').replace('\"', '\\\\\"') + '\"'\n\n\ndef _describe_step(step):\n    kind = step[\"k\"]\n    if kind in (\"css\", \"xpath\"):\n        return f\"locator({_q(step['v'])})\"\n    if kind == \"role\":\n        parts = [_q(step[\"role\"])]\n        if step.get(\"name\") is not None:\n            parts.append(f\"name={_q(step['name'])}\")\n        if step.get(\"exact\"):\n            parts.append(\"exact=True\")\n        return f\"get_by_role({', '.join(parts)})\"\n    if kind == \"filter\":\n        parts = []\n        if step.get(\"hasText\") is not None:\n            parts.append(f\"has_text={_q(step['hasText'])}\")\n        if step.get(\"hasNotText\") is not None:\n            parts.append(f\"has_not_text={_q(step['hasNotText'])}\")\n        return f\"filter({', '.join(parts)})\"\n    if kind == \"nth\":\n        return f\"nth({step['v']})\"\n    if kind in (\"first\", \"last\"):\n        return kind\n    simple = {\n        \"text\": \"get_by_text\", \"label\": \"get_by_label\",\n        \"placeholder\": \"get_by_placeholder\", \"testid\": \"get_by_test_id\",\n        \"alttext\": \"get_by_alt_text\", \"title\": \"get_by_title\",\n    }\n    if kind in simple:\n        suffix = \", exact=True\" if step.get(\"exact\") else \"\"\n        return f\"{simple[kind]}({_q(step['v'])}{suffix})\"\n    return kind\n\n\ndef _describe(chain):\n    return \".\".join(_describe_step(step) for step in chain)\n\n\ndef _selector_step(selector):\n    \"\"\"Split Playwright's engine prefixes off a raw selector string.\"\"\"\n    text = selector.strip()\n    if text.startswith(\"xpath=\"):\n        return {\"k\": \"xpath\", \"v\": text[6:]}\n    if text.startswith((\"//\", \"(//\", \"..\")):\n        return {\"k\": \"xpath\", \"v\": text}\n    if text.startswith(\"text=\"):\n        return {\"k\": \"text\", \"v\": text[5:]}\n    if text.startswith(\"css=\"):\n        return {\"k\": \"css\", \"v\": text[4:]}\n    return {\"k\": \"css\", \"v\": text}\n\n\n# --------------------------------------------------------------------------\n# Locator\n# --------------------------------------------------------------------------\n\nclass Locator:\n    \"\"\"An address for one or more elements. Creating it touches nothing;\n    every action re-finds the element from scratch.\"\"\"\n\n    def __init__(self, chain):\n        self._chain = list(chain)\n\n    # ---------------------------------------------------------- building\n\n    def locator(self, selector):\n        return Locator(self._chain + [_selector_step(selector)])\n\n    def get_by_role(self, role, name=None, exact=False):\n        return Locator(self._chain + [\n            {\"k\": \"role\", \"role\": role, \"name\": name, \"exact\": bool(exact)}\n        ])\n\n    def get_by_text(self, text, exact=False):\n        return Locator(self._chain + [{\"k\": \"text\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_label(self, text, exact=False):\n        return Locator(self._chain + [{\"k\": \"label\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_placeholder(self, text, exact=False):\n        return Locator(self._chain + [{\"k\": \"placeholder\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_test_id(self, test_id):\n        return Locator(self._chain + [{\"k\": \"testid\", \"v\": test_id}])\n\n    def get_by_alt_text(self, text, exact=False):\n        return Locator(self._chain + [{\"k\": \"alttext\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_title(self, text, exact=False):\n        return Locator(self._chain + [{\"k\": \"title\", \"v\": text, \"exact\": bool(exact)}])\n\n    def filter(self, has_text=None, has_not_text=None):\n        return Locator(self._chain + [\n            {\"k\": \"filter\", \"hasText\": has_text, \"hasNotText\": has_not_text}\n        ])\n\n    @property\n    def first(self):\n        return Locator(self._chain + [{\"k\": \"first\"}])\n\n    @property\n    def last(self):\n        return Locator(self._chain + [{\"k\": \"last\"}])\n\n    def nth(self, index):\n        return Locator(self._chain + [{\"k\": \"nth\", \"v\": index}])\n\n    def __repr__(self):\n        return f\"<Locator {_describe(self._chain)}>\"\n\n    # ----------------------------------------------------------- internals\n\n    def _chain_json(self):\n        return json.dumps(self._chain)\n\n    def _once(self, action, args=()):\n        \"\"\"One attempt. Returns the parsed {ok, value} / {ok, code} dict.\"\"\"\n        return json.loads(_runtime.BRIDGE.perform(\n            self._chain_json(), action, json.dumps(list(args)), -1\n        ))\n\n    def _strict_error(self, method, count):\n        described = _describe(self._chain)\n        info = json.loads(_runtime.BRIDGE.describe(self._chain_json()))\n        headline = (f\"Locator.{method}: Error: strict mode violation: \"\n                    f\"{described} resolved to {count} elements:\")\n        lines = [headline]\n        for index, sample in enumerate(info[\"samples\"], start=1):\n            lines.append(f\"    {index}) {sample}\")\n        lines.append(\"\")\n        lines.append(\"Add .first, .nth(i) or a more specific locator to pick one.\")\n        return Error(\"\\n\".join(lines))\n\n    def _timeout_error(self, method, timeout, last):\n        \"\"\"Build the message Playwright would print - it is teaching material.\"\"\"\n        described = _describe(self._chain)\n        log = [f\"  - waiting for {described}\"]\n        code = (last or {}).get(\"code\")\n        detail = (last or {}).get(\"detail\", \"\")\n        if code == \"not_visible\":\n            log.append(\"  - locator resolved to a hidden element\")\n            log.append(f\"  - retrying {method} action\")\n        elif code == \"not_enabled\":\n            log.append(\"  - element is not enabled\")\n            log.append(f\"  - retrying {method} action\")\n        elif code == \"not_editable\":\n            log.append(\"  - element is not an editable input\")\n        elif code == \"intercepted\":\n            log.append(f\"  - {detail} intercepts pointer events\")\n            log.append(f\"  - retrying {method} action\")\n        elif code == \"no_option\":\n            log.append(\"  - no <option> matched the value you asked for\")\n        return TimeoutError(\n            f\"Locator.{method}: Timeout {timeout}ms exceeded.\\nCall log:\\n\"\n            + \"\\n\".join(log)\n        )\n\n    def _run(self, method, action=None, args=(), timeout=None):\n        \"\"\"Do something to the element, retrying until it is actionable.\"\"\"\n        action = action or method\n        limit = DEFAULT_TIMEOUT if timeout is None else timeout\n        waited = 0\n        last = None\n        while True:\n            result = self._once(action, args)\n            if result[\"ok\"]:\n                _runtime.record(method, _describe(self._chain), self._chain, args)\n                return result[\"value\"]\n            code = result[\"code\"]\n            if code == \"strict\":\n                # Strict violations are a bug in the locator, not a delay:\n                # real Playwright fails immediately, and so do we.\n                raise self._strict_error(method, int(result[\"detail\"]))\n            if code == \"unsupported\":\n                raise NotImplementedError(\n                    f\"playwright_lite does not implement Locator.{action}() yet.\"\n                )\n            last = result\n            if waited >= limit:\n                _runtime.record(method, _describe(self._chain), self._chain, args,\n                                ok=False, detail=code)\n                raise self._timeout_error(method, limit, last)\n            step = _FINE_POLL if waited < _FINE_WINDOW else _COARSE_POLL\n            _runtime.BRIDGE.tick(step)\n            waited += step\n\n    # ------------------------------------------------------------- actions\n\n    def click(self, timeout=None):\n        self._run(\"click\", timeout=timeout)\n\n    def hover(self, timeout=None):\n        self._run(\"hover\", timeout=timeout)\n\n    def focus(self, timeout=None):\n        self._run(\"focus\", timeout=timeout)\n\n    def fill(self, value, timeout=None):\n        self._run(\"fill\", args=[value], timeout=timeout)\n\n    def press(self, key, timeout=None):\n        self._run(\"press\", args=[key], timeout=timeout)\n\n    def check(self, timeout=None):\n        self._run(\"check\", timeout=timeout)\n\n    def uncheck(self, timeout=None):\n        self._run(\"uncheck\", timeout=timeout)\n\n    def select_option(self, value=None, label=None, timeout=None):\n        self._run(\"select_option\", args=[value, label], timeout=timeout)\n\n    def scroll_into_view_if_needed(self, timeout=None):\n        self._run(\"scroll_into_view_if_needed\", timeout=timeout)\n\n    # --------------------------------------------------------------- reads\n\n    def inner_text(self, timeout=None):\n        return self._run(\"inner_text\", timeout=timeout)\n\n    def text_content(self, timeout=None):\n        return self._run(\"text_content\", timeout=timeout)\n\n    def input_value(self, timeout=None):\n        return self._run(\"input_value\", timeout=timeout)\n\n    def get_attribute(self, name, timeout=None):\n        return self._run(\"get_attribute\", args=[name], timeout=timeout)\n\n    def count(self):\n        \"\"\"How many elements match right now. Never waits - this is the\n        one place Playwright deliberately gives you a snapshot.\"\"\"\n        return int(_runtime.BRIDGE.count(self._chain_json()))\n\n    def all_inner_texts(self):\n        \"\"\"Every match's text, as a plain list. Zero matches is fine here -\n        this is the one read that does not insist on finding anything.\"\"\"\n        texts = json.loads(_runtime.BRIDGE.all_texts(self._chain_json()))\n        # Recorded (unlike count(), which expect().to_have_count polls in a\n        # loop) because a learner calls this once, on purpose.\n        _runtime.record(\"all_inner_texts\", _describe(self._chain), self._chain)\n        return texts\n\n    def _immediate(self, action, default):\n        if self.count() == 0:\n            return default\n        result = self._once(action)\n        if not result[\"ok\"]:\n            if result[\"code\"] == \"strict\":\n                raise self._strict_error(action, int(result[\"detail\"]))\n            return default\n        _runtime.record(action, _describe(self._chain), self._chain)\n        return result[\"value\"]\n\n    def is_visible(self):\n        \"\"\"A snapshot, NOT a wait. If you find yourself writing\n        `assert locator.is_visible()`, you wanted expect(...) instead.\"\"\"\n        return bool(self._immediate(\"is_visible\", False))\n\n    def is_enabled(self):\n        return bool(self._immediate(\"is_enabled\", False))\n\n    def is_checked(self):\n        return bool(self._immediate(\"is_checked\", False))\n\n    def is_hidden(self):\n        return not self.is_visible()\n\n\n# --------------------------------------------------------------------------\n# Page\n# --------------------------------------------------------------------------\n\nclass Page:\n    \"\"\"One browser tab. The `page` fixture hands you one of these.\"\"\"\n\n    def locator(self, selector):\n        return Locator([_selector_step(selector)])\n\n    def get_by_role(self, role, name=None, exact=False):\n        return Locator([{\"k\": \"role\", \"role\": role, \"name\": name, \"exact\": bool(exact)}])\n\n    def get_by_text(self, text, exact=False):\n        return Locator([{\"k\": \"text\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_label(self, text, exact=False):\n        return Locator([{\"k\": \"label\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_placeholder(self, text, exact=False):\n        return Locator([{\"k\": \"placeholder\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_test_id(self, test_id):\n        return Locator([{\"k\": \"testid\", \"v\": test_id}])\n\n    def get_by_alt_text(self, text, exact=False):\n        return Locator([{\"k\": \"alttext\", \"v\": text, \"exact\": bool(exact)}])\n\n    def get_by_title(self, text, exact=False):\n        return Locator([{\"k\": \"title\", \"v\": text, \"exact\": bool(exact)}])\n\n    # ---------------------------------------------------------- navigation\n\n    def goto(self, url):\n        # Accept either a full address or a bare path, so both\n        # page.goto(BASE_URL + \"/login\") and page.goto(\"/login\") work.\n        path = url\n        for prefix in (\"https://automationexercise.com\", \"http://automationexercise.com\"):\n            if path.startswith(prefix):\n                path = path[len(prefix):]\n                break\n        if not path.startswith(\"/\"):\n            raise Error(f\"page.goto: {url} is not a page of this practice site.\")\n        result = _runtime.BRIDGE.goto_path(path)\n        _runtime.record(\"goto\", path, [], [url])\n        return result\n\n    def reload(self):\n        _runtime.record(\"reload\", self.url, [])\n        return _runtime.BRIDGE.reload()\n\n    def go_back(self):\n        _runtime.record(\"go_back\", self.url, [])\n        return _runtime.BRIDGE.go_back()\n\n    @property\n    def url(self):\n        return _runtime.BRIDGE.url()\n\n    def title(self):\n        return _runtime.BRIDGE.title()\n\n    def wait_for_timeout(self, milliseconds):\n        \"\"\"Playwright has this, and Playwright tells you not to use it.\n        It is here so the lesson about it can be honest.\"\"\"\n        _runtime.record(\"wait_for_timeout\", \"\", [], [milliseconds])\n        _runtime.BRIDGE.tick(milliseconds)\n\n    def __repr__(self):\n        return f\"<Page url={self.url!r}>\"\n\n\n# --------------------------------------------------------------------------\n# expect()\n# --------------------------------------------------------------------------\n\ndef _assertion_error(subject, expectation, actual, matcher, timeout, target):\n    \"\"\"The failure format from the guide's \"What a failure looks like\".\"\"\"\n    lines = [\n        f\"{subject} expected {expectation}\",\n        f\"Actual value: {actual}\",\n        \"Call log:\",\n        f\"  - expect({subject.lower()}).{matcher} with timeout {timeout}ms\",\n    ]\n    if target:\n        lines.append(f\"  - waiting for {target}\")\n    return AssertionError(\"\\n\".join(lines))\n\n\nclass LocatorAssertions:\n    def __init__(self, locator, timeout=None, is_not=False):\n        self._locator = locator\n        self._timeout = _expect_timeout if timeout is None else timeout\n        self._is_not = is_not\n\n    # -------------------------------------------------------------- engine\n\n    def _poll(self, matcher, expectation, probe, timeout=None):\n        \"\"\"Retry `probe` until it reports success - the web-first wait\n        that makes expect() different from a bare assert.\"\"\"\n        limit = self._timeout if timeout is None else timeout\n        waited = 0\n        actual = \"\"\n        while True:\n            ok, actual = probe()\n            if ok != self._is_not:\n                _runtime.record(\n                    f\"expect.{'not_' if self._is_not else ''}{matcher}\",\n                    _describe(self._locator._chain), self._locator._chain,\n                )\n                return\n            if waited >= limit:\n                _runtime.record(\n                    f\"expect.{'not_' if self._is_not else ''}{matcher}\",\n                    _describe(self._locator._chain), self._locator._chain,\n                    ok=False, detail=str(actual),\n                )\n                phrase = (\"not \" if self._is_not else \"\") + expectation\n                raise _assertion_error(\"Locator\", phrase, actual, matcher,\n                                       limit, _describe(self._locator._chain))\n            step = _FINE_POLL if waited < _FINE_WINDOW else _COARSE_POLL\n            _runtime.BRIDGE.tick(step)\n            waited += step\n\n    def _info(self):\n        return json.loads(_runtime.BRIDGE.describe(self._locator._chain_json()))\n\n    def _single_text(self):\n        info = self._info()\n        if info[\"count\"] == 0:\n            return None\n        return info[\"texts\"][0]\n\n    # ------------------------------------------------------------ matchers\n\n    def to_be_visible(self, timeout=None):\n        self._poll(\"to_be_visible\", \"to be visible\",\n                   lambda: (self._info()[\"visible\"] > 0, \"hidden\"), timeout)\n\n    def not_to_be_visible(self, timeout=None):\n        LocatorAssertions(self._locator, self._timeout, not self._is_not) \\\n            .to_be_visible(timeout)\n\n    def to_be_hidden(self, timeout=None):\n        self._poll(\"to_be_hidden\", \"to be hidden\",\n                   lambda: (self._info()[\"visible\"] == 0, \"visible\"), timeout)\n\n    def not_to_be_hidden(self, timeout=None):\n        LocatorAssertions(self._locator, self._timeout, not self._is_not) \\\n            .to_be_hidden(timeout)\n\n    def to_have_text(self, expected, timeout=None):\n        def probe():\n            text = self._single_text()\n            return (text is not None and _norm(text) == _norm(expected),\n                    \"<no element found>\" if text is None else text)\n        self._poll(\"to_have_text\", f\"to have text {expected!r}\", probe, timeout)\n\n    def not_to_have_text(self, expected, timeout=None):\n        LocatorAssertions(self._locator, self._timeout, not self._is_not) \\\n            .to_have_text(expected, timeout)\n\n    def to_contain_text(self, expected, timeout=None):\n        def probe():\n            text = self._single_text()\n            return (text is not None and _norm(expected) in _norm(text),\n                    \"<no element found>\" if text is None else text)\n        self._poll(\"to_contain_text\", f\"to contain text {expected!r}\", probe, timeout)\n\n    def not_to_contain_text(self, expected, timeout=None):\n        LocatorAssertions(self._locator, self._timeout, not self._is_not) \\\n            .to_contain_text(expected, timeout)\n\n    def to_have_value(self, expected, timeout=None):\n        def probe():\n            if self._locator.count() == 0:\n                return False, \"<no element found>\"\n            value = self._locator._once(\"input_value\")\n            actual = value.get(\"value\") if value[\"ok\"] else \"<not an input>\"\n            return actual == expected, actual\n        self._poll(\"to_have_value\", f\"to have value {expected!r}\", probe, timeout)\n\n    def to_have_count(self, expected, timeout=None):\n        def probe():\n            count = self._locator.count()\n            return count == expected, count\n        self._poll(\"to_have_count\", f\"to have count {expected}\", probe, timeout)\n\n    def to_have_attribute(self, name, value, timeout=None):\n        def probe():\n            if self._locator.count() == 0:\n                return False, \"<no element found>\"\n            result = self._locator._once(\"get_attribute\", [name])\n            actual = result.get(\"value\") if result[\"ok\"] else None\n            return actual == value, actual\n        self._poll(\"to_have_attribute\", f\"to have attribute {name}={value!r}\",\n                   probe, timeout)\n\n    def to_be_enabled(self, timeout=None):\n        self._poll(\"to_be_enabled\", \"to be enabled\",\n                   lambda: (self._locator.is_enabled(), \"disabled\"), timeout)\n\n    def to_be_disabled(self, timeout=None):\n        self._poll(\"to_be_disabled\", \"to be disabled\",\n                   lambda: (not self._locator.is_enabled(), \"enabled\"), timeout)\n\n    def to_be_checked(self, timeout=None):\n        self._poll(\"to_be_checked\", \"to be checked\",\n                   lambda: (self._locator.is_checked(), \"unchecked\"), timeout)\n\n    def not_to_be_checked(self, timeout=None):\n        LocatorAssertions(self._locator, self._timeout, not self._is_not) \\\n            .to_be_checked(timeout)\n\n    def to_be_empty(self, timeout=None):\n        self._poll(\"to_be_empty\", \"to be empty\",\n                   lambda: (_norm(self._single_text() or \"\") == \"\",\n                            self._single_text()), timeout)\n\n\nclass PageAssertions:\n    def __init__(self, page, timeout=None):\n        self._page = page\n        self._timeout = _expect_timeout if timeout is None else timeout\n\n    def _poll(self, matcher, expectation, probe, subject_actual, timeout=None):\n        limit = self._timeout if timeout is None else timeout\n        waited = 0\n        while True:\n            if probe():\n                _runtime.record(f\"expect.{matcher}\", \"page\", [])\n                return\n            if waited >= limit:\n                _runtime.record(f\"expect.{matcher}\", \"page\", [], ok=False)\n                raise _assertion_error(\"Page\", expectation, subject_actual(),\n                                       matcher, limit, None)\n            step = _FINE_POLL if waited < _FINE_WINDOW else _COARSE_POLL\n            _runtime.BRIDGE.tick(step)\n            waited += step\n\n    def to_have_url(self, expected, timeout=None):\n        self._poll(\"to_have_url\", f\"to have URL {expected!r}\",\n                   lambda: self._page.url == expected,\n                   lambda: self._page.url, timeout)\n\n    def to_have_title(self, expected, timeout=None):\n        self._poll(\"to_have_title\", f\"to have title {expected!r}\",\n                   lambda: self._page.title() == expected,\n                   lambda: self._page.title(), timeout)\n\n\ndef _norm(text):\n    return \" \".join(str(text).split())\n\n\ndef expect(subject, timeout=None):\n    \"\"\"Playwright's web-first assertion. It RETRIES until the condition\n    holds or the timeout runs out - which is why you never need a sleep.\"\"\"\n    if isinstance(subject, Page):\n        return PageAssertions(subject, timeout)\n    if isinstance(subject, Locator):\n        return LocatorAssertions(subject, timeout)\n    raise Error(\n        \"expect() takes a Page or a Locator. \"\n        f\"You passed {type(subject).__name__} - did you call .inner_text() \"\n        \"or .count() by mistake? Those give plain values, so they need a \"\n        \"plain assert (and lose the automatic waiting).\"\n    )\n\n\ndef _set_options(timeout=None):\n    \"\"\"expect.set_options(timeout=...) - matches fixtures/browser.py.\"\"\"\n    global _expect_timeout\n    if timeout is not None:\n        _expect_timeout = timeout\n\n\nexpect.set_options = _set_options\n", "quest/__init__.py": "\"\"\"The quest site's own Python: the code-review rubric and the run harness.\n\nKept separate from playwright_lite so the shim stays a pure Playwright\nsurface with nothing quest-specific leaking into it.\n\"\"\"\n", "quest/harness.py": "\"\"\"quest/harness.py - runs one attempt at a challenge, the way pytest would.\n\nThe order matters and is the same order a good reviewer works in:\n\n    1. Does it parse?            -> a SyntaxError, with the line number\n    2. Would a reviewer approve? -> the AST rubric (see rubric.py)\n    3. Does it actually work?    -> execute it against the practice shop\n\nStep 2 comes before step 3 on purpose. Code with a `time.sleep()` in it\nis not run at all: a sleep would block the whole browser tab for real\nseconds, and more importantly a senior reviewer stops at the sleep too.\n\nEverything crosses into JavaScript as JSON, so nothing here depends on\nPyodide's object proxies.\n\"\"\"\n\nimport io\nimport json\nimport os\nimport sys\nimport time\nimport traceback\n\nfrom playwright_lite import _runtime\nfrom playwright_lite.sync_api import Page\n\nfrom quest import rubric\n\nLEARNER_FILE = \"test_challenge.py\"\nLEARNER_DIR = \"/learner\"\n\n\ndef install_guards():\n    \"\"\"Disable the things that would freeze the tab. Called once at boot.\"\"\"\n    def blocked_sleep(seconds):\n        raise RuntimeError(\n            \"time.sleep() is switched off on the quest site.\\n\"\n            \"That is not censorship - it is the lesson. A sleep would stop \"\n            \"this page for \" + str(seconds) + \" real seconds and STILL not \"\n            \"wait for the thing you care about. Use expect(...), which \"\n            \"retries until the page is ready.\"\n        )\n\n    time.sleep = blocked_sleep\n\n    os.makedirs(LEARNER_DIR, exist_ok=True)\n    if LEARNER_DIR not in sys.path:\n        sys.path.insert(0, LEARNER_DIR)\n\n\ndef _syntax_report(error, cell):\n    \"\"\"A SyntaxError, explained without the CPython jargon.\"\"\"\n    return {\n        \"cell\": cell,\n        \"line\": error.lineno or 0,\n        \"offset\": error.offset or 0,\n        \"message\": error.msg,\n        \"text\": (error.text or \"\").rstrip(\"\\n\"),\n    }\n\n\ndef _learner_traceback(exc):\n    \"\"\"Show the learner's own frames, not ours.\"\"\"\n    trace = traceback.TracebackException.from_exception(exc)\n    ours = [\n        frame for frame in trace.stack\n        if frame.filename == LEARNER_FILE or frame.filename.startswith(LEARNER_DIR)\n    ]\n    if ours:\n        trace.stack = traceback.StackSummary.from_list(ours)\n    line = ours[-1].lineno if ours else 0\n    return \"\".join(trace.format()), line\n\n\ndef _write_cells(cells):\n    \"\"\"Put the learner's extra files (page objects, conftest) on sys.path.\"\"\"\n    written = []\n    for cell in cells:\n        name = cell.get(\"name\")\n        if not name:\n            continue\n        path = os.path.join(LEARNER_DIR, name)\n        os.makedirs(os.path.dirname(path), exist_ok=True)\n        # A package needs an __init__.py to be importable, and the learner\n        # should not have to remember that in a browser text box.\n        folder = os.path.dirname(path)\n        while folder != LEARNER_DIR and folder:\n            init = os.path.join(folder, \"__init__.py\")\n            if not os.path.exists(init):\n                with open(init, \"w\", encoding=\"utf-8\") as handle:\n                    handle.write(\"\")\n            folder = os.path.dirname(folder)\n        with open(path, \"w\", encoding=\"utf-8\") as handle:\n            handle.write(cell.get(\"source\", \"\"))\n        written.append(name)\n    return written\n\n\ndef _forget_learner_modules():\n    \"\"\"Drop last attempt's modules so an edit actually takes effect.\"\"\"\n    for name, module in list(sys.modules.items()):\n        origin = getattr(getattr(module, \"__spec__\", None), \"origin\", None)\n        if origin and str(origin).startswith(LEARNER_DIR):\n            del sys.modules[name]\n\n\ndef run(payload_json):\n    \"\"\"Grade and run one attempt. Returns a JSON string (see ARCHITECTURE.md).\"\"\"\n    payload = json.loads(payload_json)\n    source = payload.get(\"source\", \"\")\n    cells = payload.get(\"cells\", [])\n\n    result = {\n        \"ok\": False,\n        \"phase\": \"syntax\",\n        \"stdout\": \"\",\n        \"log\": [],\n        \"findings\": [],\n        \"syntax\": None,\n        \"error\": None,\n        \"errorLine\": 0,\n        \"virtualMs\": 0,\n    }\n\n    # ---------------------------------------------------------- 1. parse\n    pieces = [{\"name\": LEARNER_FILE, \"source\": source, \"rubric\": payload.get(\"rubric\"),\n               \"label\": \"your test\"}] + cells\n    for piece in pieces:\n        try:\n            compile(piece.get(\"source\", \"\"), piece.get(\"name\", LEARNER_FILE), \"exec\")\n        except SyntaxError as error:\n            result[\"syntax\"] = _syntax_report(error, piece.get(\"name\", LEARNER_FILE))\n            result[\"errorLine\"] = error.lineno or 0\n            return json.dumps(result)\n\n    # --------------------------------------------------------- 2. rubric\n    result[\"phase\"] = \"rubric\"\n    findings = []\n    for piece in pieces:\n        config = {\"cell_label\": piece.get(\"label\", piece.get(\"name\"))}\n        for finding in rubric.review(piece.get(\"source\", \"\"), piece.get(\"rubric\"), config):\n            finding[\"cell\"] = piece.get(\"name\", LEARNER_FILE)\n            findings.append(finding)\n    result[\"findings\"] = findings\n    if any(f[\"severity\"] == \"error\" for f in findings):\n        result[\"errorLine\"] = next(f[\"line\"] for f in findings if f[\"severity\"] == \"error\")\n        return json.dumps(result)\n\n    # ------------------------------------------------------- 3. execute\n    result[\"phase\"] = \"run\"\n    _runtime.reset_log()\n    _forget_learner_modules()\n    _write_cells(cells)\n\n    page = Page()\n    namespace = {\"__name__\": \"learner_test\", \"__file__\": LEARNER_FILE}\n    captured = io.StringIO()\n    real_stdout = sys.stdout\n    sys.stdout = captured\n    try:\n        exec(compile(source, LEARNER_FILE, \"exec\"), namespace)  # noqa: S102\n\n        tests = [\n            value for name, value in namespace.items()\n            if name.startswith(\"test_\") and callable(value)\n        ]\n        if not tests:\n            result[\"error\"] = (\n                \"No test function found.\\n\"\n                \"pytest collects functions whose name starts with test_, so \"\n                \"your code needs to live inside one:\\n\\n\"\n                \"    def test_something_useful(page):\\n        ...\"\n            )\n        else:\n            for test in tests:\n                # Match pytest: pass the `page` fixture only if asked for.\n                if test.__code__.co_argcount:\n                    test(page)\n                else:\n                    test()\n            result[\"ok\"] = True\n            result[\"phase\"] = \"pass\"\n    except Exception as error:                              # noqa: BLE001\n        text, line = _learner_traceback(error)\n        result[\"error\"] = text\n        result[\"errorLine\"] = line\n    finally:\n        sys.stdout = real_stdout\n        result[\"stdout\"] = captured.getvalue()\n        result[\"log\"] = list(_runtime.ACTION_LOG)\n        result[\"virtualMs\"] = _runtime.BRIDGE.now() if _runtime.BRIDGE else 0\n\n    return json.dumps(result)\n", "quest/rubric.py": "\"\"\"The code-review rubric: the kit's conventions, enforced with `ast`.\n\nWhy an AST and not a regular expression? Because grading must be about\nwhat the code MEANS. `# never use time.sleep` is a comment, not a sleep;\n`assert page.get_by_text(\"Cart\").is_visible()` is a real problem even\nthough it contains the word \"expect\" nowhere. Parsing gets both right.\n\nEvery finding is written in the voice of a senior reviewer leaving a\nkind, specific comment on a pull request - because a red X teaches\nnothing, and \"no time.sleep\" without the reason teaches only obedience.\n\nSeverities:\n    error   - blocks the challenge. A reviewer would not approve this.\n    advice  - passes, but costs the clean-run bonus. Worth knowing.\n\"\"\"\n\nimport ast\n\n# Methods that answer \"what is true RIGHT NOW\" and never wait. Wrapping\n# one in a bare assert throws away Playwright's auto-waiting, which is\n# the single most common cause of flaky beginner tests.\nSNAPSHOT_MATCHERS = {\n    \"is_visible\": \"expect(locator).to_be_visible()\",\n    \"is_hidden\": \"expect(locator).to_be_hidden()\",\n    \"is_enabled\": \"expect(locator).to_be_enabled()\",\n    \"is_checked\": \"expect(locator).to_be_checked()\",\n    \"count\": \"expect(locator).to_have_count(n)\",\n    \"inner_text\": \"expect(locator).to_have_text(...) or .to_contain_text(...)\",\n    \"text_content\": \"expect(locator).to_have_text(...)\",\n    \"input_value\": \"expect(locator).to_have_value(...)\",\n    \"get_attribute\": \"expect(locator).to_have_attribute(name, value)\",\n}\n\nLOCATOR_BUILDERS = {\n    \"locator\", \"get_by_role\", \"get_by_text\", \"get_by_label\",\n    \"get_by_placeholder\", \"get_by_test_id\", \"get_by_alt_text\", \"get_by_title\",\n}\n\n\ndef _finding(rule, severity, node, title, message):\n    return {\n        \"rule\": rule,\n        \"severity\": severity,\n        # A whole-file finding (no assertion anywhere, no test function)\n        # has no node of its own, so point at the first line rather than\n        # at a meaningless line 0.\n        \"line\": getattr(node, \"lineno\", None) or _first_line(node),\n        \"title\": title,\n        \"message\": message,\n    }\n\n\ndef _first_line(node):\n    body = getattr(node, \"body\", None)\n    if body:\n        return getattr(body[0], \"lineno\", 1)\n    return 1\n\n\ndef _calls(tree):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Call):\n            yield node\n\n\ndef _attr_name(node):\n    \"\"\"The method name of `something.method(...)`, else None.\"\"\"\n    if isinstance(node.func, ast.Attribute):\n        return node.func.attr\n    return None\n\n\ndef _first_string_arg(node):\n    if not node.args:\n        return None\n    first = node.args[0]\n    if isinstance(first, ast.Constant) and isinstance(first.value, str):\n        return first.value\n    return None\n\n\n# --------------------------------------------------------------------------\n# The rules\n# --------------------------------------------------------------------------\n\ndef rule_no_sleep(tree, _config):\n    \"\"\"time.sleep() and wait_for_timeout() - fixed waits, always wrong.\"\"\"\n    findings = []\n    for node in _calls(tree):\n        name = _attr_name(node)\n        is_sleep = name == \"sleep\" or (\n            isinstance(node.func, ast.Name) and node.func.id == \"sleep\"\n        )\n        if is_sleep:\n            findings.append(_finding(\n                \"no-sleep\", \"error\", node,\n                \"Replace the sleep with an expect()\",\n                \"A fixed sleep is wrong twice over: too short on a slow day \"\n                \"(the test fails for no reason) and too long on a fast day \"\n                \"(every run pays for it). Whatever you are waiting FOR, there \"\n                \"is an expect() that says it out loud - expect(...)\"\n                \".to_be_visible(), .to_have_text(), .to_have_count() - and it \"\n                \"waits exactly as long as needed, no longer. Tell me what you \"\n                \"were waiting for and we will find the matcher together.\",\n            ))\n        if name == \"wait_for_timeout\":\n            findings.append(_finding(\n                \"no-sleep\", \"error\", node,\n                \"wait_for_timeout() is a sleep in a Playwright costume\",\n                \"It really is in the API, and Playwright's own docs tell you \"\n                \"not to use it. Same reasoning as time.sleep(): it waits a \"\n                \"guessed amount instead of waiting for the thing you actually \"\n                \"care about. Use an expect() on the element that proves the \"\n                \"page is ready.\",\n            ))\n    return findings\n\n\ndef rule_expect_over_assert(tree, _config):\n    \"\"\"`assert locator.is_visible()` where expect() belongs.\"\"\"\n    findings = []\n    for node in ast.walk(tree):\n        if not isinstance(node, ast.Assert):\n            continue\n        for call in [n for n in ast.walk(node.test) if isinstance(n, ast.Call)]:\n            name = _attr_name(call)\n            if name in SNAPSHOT_MATCHERS:\n                findings.append(_finding(\n                    \"expect-over-assert\", \"error\", node,\n                    f\"Use expect() instead of assert ....{name}()\",\n                    f\".{name}() answers 'is this true at this exact \"\n                    \"millisecond?' and never waits, so this assert passes or \"\n                    \"fails depending on how busy the machine was - the \"\n                    \"definition of a flaky test. Rewrite it as \"\n                    f\"{SNAPSHOT_MATCHERS[name]}, which retries until the page \"\n                    \"catches up. Keep the plain assert for values you have \"\n                    \"already read into a variable (comparing two prices, \"\n                    \"checking a list length) - that is the right tool there.\",\n                ))\n    return findings\n\n\ndef rule_has_assertion(tree, _config):\n    \"\"\"A script with no assertion is not a test.\"\"\"\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Assert):\n            return []\n        is_expect_call = (\n            isinstance(node, ast.Call)\n            and isinstance(node.func, ast.Name)\n            and node.func.id == \"expect\"\n        )\n        if is_expect_call:\n            return []\n    return [_finding(\n        \"has-assertion\", \"error\", tree,\n        \"This script never checks anything\",\n        \"It drives the page perfectly well, but without an assertion it can \"\n        \"never fail - so it can never tell you the site broke. Add the \"\n        \"expect() that states what you believe should be true once the \"\n        \"actions are done. That line is the reason the test exists.\",\n    )]\n\n\ndef rule_no_xpath(tree, _config):\n    findings = []\n    for node in _calls(tree):\n        if _attr_name(node) != \"locator\":\n            continue\n        selector = _first_string_arg(node)\n        if selector and selector.startswith((\"//\", \"xpath=\")):\n            findings.append(_finding(\n                \"no-xpath\", \"advice\", node,\n                \"An XPath here, where a role locator would read better\",\n                \"XPath works, and one day you will need it. But it describes \"\n                \"the page's internal shape, so it breaks the moment a \"\n                \"developer wraps something in a new <div> - and the next \"\n                \"person to read it has to decode it. Reach for \"\n                \"get_by_role(...) first: it finds the element the way a user \"\n                \"would, by what it IS and what it SAYS.\",\n            ))\n    return findings\n\n\ndef rule_prefer_role_locator(tree, _config):\n    \"\"\"Advisory nudge in the zone where role locators were just taught.\"\"\"\n    findings = []\n    for node in _calls(tree):\n        if _attr_name(node) != \"locator\":\n            continue\n        selector = _first_string_arg(node)\n        if selector and selector.startswith((\"#\", \".\")):\n            findings.append(_finding(\n                \"prefer-role-locator\", \"advice\", node,\n                f\"Could {selector!r} be a get_by_role() instead?\",\n                \"This works and it is not a crime - the kit itself uses \"\n                \"#search_product, because that box has no visible label to \"\n                \"grab. But CSS ties your test to the page's internals. When \"\n                \"the element has a visible name (a button, a link, a \"\n                \"heading), get_by_role(...) survives redesigns that would \"\n                \"break a class selector.\",\n            ))\n    return findings\n\n\ndef rule_no_locators_here(tree, config):\n    \"\"\"Page Object Model: the test file must contain no locators at all.\"\"\"\n    findings = []\n    for node in _calls(tree):\n        name = _attr_name(node)\n        if name in LOCATOR_BUILDERS:\n            findings.append(_finding(\n                \"no-locators-here\", \"error\", node,\n                f\"A locator has escaped into {config.get('cell_label', 'the test')}\",\n                \"Layering is the whole point of the exercise: tests say WHAT \"\n                \"should be true, page objects know WHERE things are. Move \"\n                f\".{name}(...) into the page object and give it a method name \"\n                \"that reads like a user's intent - login(), add_to_cart(), \"\n                \"search_for(). Then the day the markup changes you fix one \"\n                \"line in one file instead of hunting through every test.\",\n            ))\n    return findings\n\n\ndef rule_test_function(tree, _config):\n    functions = [n for n in tree.body if isinstance(n, ast.FunctionDef)]\n    if not functions:\n        return [_finding(\n            \"test-function\", \"error\", tree, \"pytest needs a test function\",\n            \"pytest collects functions whose NAME starts with test_ - that is \"\n            \"the whole discovery rule. Wrap your code in one, for example \"\n            \"def test_search_for_a_dress(page):, and pytest will find it.\",\n        )]\n    if not any(f.name.startswith(\"test_\") for f in functions):\n        first = functions[0]\n        return [_finding(\n            \"test-function\", \"error\", first,\n            f\"Rename {first.name}() so pytest can find it\",\n            \"pytest only collects functions whose name starts with test_. \"\n            f\"As written, {first.name}() is just a function that nobody calls. \"\n            \"Name it after the behaviour it proves - \"\n            \"test_search_shows_matching_products - so a red line in CI tells \"\n            \"you what broke before you open the file.\",\n        )]\n    return []\n\n\nRULES = {\n    \"no-sleep\": rule_no_sleep,\n    \"expect-over-assert\": rule_expect_over_assert,\n    \"has-assertion\": rule_has_assertion,\n    \"no-xpath\": rule_no_xpath,\n    \"prefer-role-locator\": rule_prefer_role_locator,\n    \"no-locators-here\": rule_no_locators_here,\n    \"test-function\": rule_test_function,\n}\n\n# Applied to every challenge whether it asks for them or not. These two\n# are the kit's non-negotiables.\nALWAYS = [\"no-sleep\"]\n\n\ndef review(source, requested=None, config=None):\n    \"\"\"Run the rubric over one piece of learner code.\n\n    `requested` is the challenge's rubric list: names, or\n    {\"rule\": name, \"severity\": \"advice\"} to soften one.\n    Returns [] for code that parses; a SyntaxError propagates to the\n    caller, which reports it with the line number.\n    \"\"\"\n    tree = ast.parse(source)\n    config = config or {}\n\n    wanted = {name: None for name in ALWAYS}\n    for entry in requested or []:\n        if isinstance(entry, str):\n            wanted[entry] = None\n        else:\n            wanted[entry[\"rule\"]] = entry.get(\"severity\")\n\n    findings = []\n    for name, override in wanted.items():\n        rule = RULES.get(name)\n        if rule is None:\n            continue\n        for finding in rule(tree, config):\n            if override:\n                finding[\"severity\"] = override\n            findings.append(finding)\n\n    findings.sort(key=lambda f: (f[\"severity\"] != \"error\", f[\"line\"]))\n    return findings\n"};
